<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,s.business_name,s.trust_score FROM products p JOIN smes s ON s.id=p.sme_id WHERE p.id=? AND p.status='active'");$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Product not found.');}$pageTitle=$product['name'];include __DIR__.'/../includes/partials/header.php';?><div class="product-detail"><div><div class="no-image-placeholder large"><?=e(mb_substr($product['name'],0,1))?></div></div><div><h1><?=e($product['name'])?></h1><p>Sold by <strong><?=e($product['business_name'])?></strong> · Trust Score <?=number_format((float)$product['trust_score'],0)?>/100</p><h2>Rs <?=number_format((float)$product['price'],2)?></h2><p><?=nl2br(e($product['description']))?></p><p>Stock: <?=((int)$product['stock_quantity'])?></p><?php if((int)$product['stock_quantity']>0):?><form method="post" action="cart.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$id?>"><label>Quantity <input type="number" name="quantity" value="1" min="1" max="<?=((int)$product['stock_quantity'])?>"></label><button class="btn-primary">Add to Cart</button></form><?php else:?><p>Out of stock.</p><?php endif;?></div></div><?php include __DIR__.'/../includes/partials/footer.php';?>